# -*- coding: utf-8 -*-
"""CTMV course, chapter 13: artificial curiosity, creativity and an inquiry agent."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "cd"))
from clib import *  # noqa
def F(n, cap): return {"type": "figure", "image": "ct-%s.svg" % n, "caption": cap}
def TB(title, head, rows): return {"type": "table", "title": title, "head": head, "rows": rows}
CHS = []

CHS.append(CH("Curiosity, creativity and an inquiry agent",
 ("Curiosity", ["Curiosity | rewards | Compression progress", "Noise | gives | No progress", "Hypothesis | is tested by | The reasoner", "Leap | is | A hypothesis that compresses", "Creativity | invents | New patterns", "Agent | plans with | Tree search", "Agent | models with | A mixture of hypotheses"]),
 ["Jürgen Schmidhuber's artificial curiosity rewards an agent for improving its own compression of what it has seen, not for being surprised. Noise surprises you forever but teaches nothing, so it earns nothing. In the vault, a good hypothesis is one that shortens the description of your notes, and an intuitive leap is such a hypothesis chosen by that score and then checked by the reasoner.",
  "Creativity is the step beyond the patterns you already know: combine two known patterns into a new one and pay for it in description length. A small agent that plans with Monte-Carlo tree search over a mixture of hypotheses, an approximation of Hutter's AIXI, can run this loop as scientific inquiry: experiment, be curious, notice that nothing known fits, invent, and predict.",
  "We measured all of it. Curiosity alone ranks hypotheses but embeddings carry only part of the signal. A language model proposes bridges across domains with almost perfect accuracy on our clear test notes. In the simulated inquiry, invention is what finds a law that is in no library, and curiosity is what keeps the agent looking when its model is wrong."],
 [("Compression progress", "How much shorter the description of your data became after learning something."), ("Artificial curiosity", "Schmidhuber's idea: reward the agent for compression progress."), ("Intuitive leap", "A hypothesis chosen because it would compress the vault, then checked by the reasoner."), ("Mixture", "Many hypotheses weighted by how simple they are and how well they predicted."), ("Monte-Carlo tree search", "Plan by simulating many futures and favouring the good ones."), ("AIXI", "Hutter's idealised agent that plans over every simple world; only approximations can run.")],
 ["Be curious about what you can learn, not what surprises you.", "A leap is a hypothesis that shortens the description, checked by the reasoner.", "Invention combines known patterns and pays a complexity cost.", "Curiosity matters most when your model class is wrong."],
 [T("A knowledge base can find a bridge by looking, but a person often finds it by a hunch: this swing is like that feedback loop. Can a machine have such a hunch in a way we can test? Here we try three ways: a curiosity score inside the vault, a language model asked to find shared mechanisms, and a small agent that does science in a simulated world."),
  F("13-1", "Curiosity chooses a hypothesis by how much it shortens the description."),
  TB("A hypothesis in the vault", ["Step", "What happens", "Example"], [["hypothesise", "state that a note is an instance of a known pattern", "resonance is positive_feedback"], ["derive", "the reasoner adds what the pattern is known to do", "resonance causes runaway_growth"], ["save", "claims the note already stated become redundant", "one claim saved"], ["score", "saved claims minus one for the new claim", "progress 0 or more"], ["verify", "the new pairs appear: same shape in other fields", "retry storm, squeal"], ["decide", "you keep or drop the suggestion", "the vault stays yours"]]),
  T("Noise earns nothing. A filler note about a weekly standup is surprising next to the rest of the vault, but no pattern predicts it, so every hypothesis about it scores minus one. Lab 5 shows both cases with the real reasoner."),
  T("The first test used embeddings alone. With patterns labelled in two or three domains and the domain part of each vector removed, the progress score labelled the other domains with precision 0.93 on templated notes and 0.53 on rewritten notes, against 0.11 to 0.19 for a plain one-shot tagger. It ranks well but is not a labeller. Inventing a brand-new pattern from embeddings alone failed: the groups were barely purer than random."),
  T("The second test asked a language model, gemma4:31b, to read 45 notes without any pattern list and group notes that share a mechanism across fields. In 60 test vaults it found 1804 of 1812 planted bridges with precision 0.99, and did not group the false friends. These planted analogies are written clearly and real notes will be harder, so treat it as a promising result, not a promise."),
  F("13-2", "An inquiry agent: experiment, learn, notice, invent, predict."),
  TB("The inquiry agent", ["Part", "What it is", "In AIXI terms"], [["model", "a mixture over hypotheses with prior two to the minus description bits", "Solomonoff-style mixture (MC-AIXI uses context trees)"], ["planner", "Monte-Carlo tree search over experiments, one sampled world per rollout", "the planning part of MC-AIXI"], ["curiosity", "reward for the information gained by an experiment", "Schmidhuber's compression progress"], ["creativity", "when nothing compresses the data, combine library patterns and add them", "model growth"], ["goal", "predict which pattern governs the system", "extrinsic reward"]]),
  T("In the simulation the agent studies a hidden system. If the law is one it knows, the planner needs one experiment and curiosity adds nothing, because a Bayesian planner already values information. If the law is a new combination, such as logistic growth, a confident planner stops after about 1.4 experiments and is right a third of the time. The curious one keeps going, sees that the data do not compress, invents, and is right 85 to 90 percent of the time. Creativity finds the law, curiosity keeps the search alive."),
  TB("Inquiry agent results", ["World", "Agent", "Right", "Experiments"], [["known law", "random experiments", "0.99", "4.0"], ["known law", "planner, with or without curiosity", "1.00", "1.0"], ["new composite law", "planner, no curiosity", "0.33", "1.4"], ["new composite law", "planner + curiosity + creativity", "0.87 to 0.90", "3.5"], ["new composite law", "no creativity, any agent", "0.00", "1 to 4"]]),
  T("Can structure alone find the same pattern in two fields? We tested four formal tools that ignore names completely, on graphs a language model drew from the notes. Weisfeiler-Lehman fingerprints and structure mapping ranked true pairs well above embeddings, anti-unification and Gromov-Wasserstein alignment did better at picking the exact pairs, but none of them matched the language model's own hunch. Structure works best as the checker."),
  F("13-3", "Propose with a language model, verify with structure, keep the rule."),
  TB("Isomorphism hunting tools", ["Tool", "What it does", "Result here"], [["Weisfeiler-Lehman", "fingerprints each graph by its neighbourhoods", "ranks pairs, AUROC 0.80"], ["structure mapping", "largest common subgraph with matching signs", "AUROC 0.82, fooled by single edges"], ["anti-unification", "common shape written as a rule with variables", "best pair picker at 0.24, gives the rule"], ["Gromov-Wasserstein", "aligns two graphs by their inner distances", "AUROC 0.84, never matched a false friend"], ["language-model hunch", "groups notes with the same mechanism", "0.99 precision; structure check keeps 99 percent right"]]),
  T("Together they invent patterns. With no pattern list given, the confirmed pairs formed 80 groups, 79 of them pure, covering 64 percent of the planted patterns. A loop with a side effect came out as a rule the reasoner can check. About two thirds of the rules were too generic, like X raises Y and Y raises Z, so keep rules with a loop or three or more edges. Patterns that are not loops, such as spare parts, are hard to draw as a few signed edges."),
  T("The limits matter. The world is small and hand-built, the inventions come from a fixed grammar, the planner is a rough approximation of AIXI, and the language-model test used clear notes. The code and numbers are in the benchmark report."),
  TB("What was measured", ["Question", "Result", "Caveat"], [["curiosity with embeddings", "precision 0.93 templated, 0.53 rewritten", "ranks, does not label on rewritten text"], ["invention from embeddings", "barely above random", "negative result"], ["language-model leap", "0.99 precision, 99.6 percent of bridges", "clear planted analogies"], ["inquiry: known law", "1 experiment, 100 percent", "curiosity adds nothing"], ["inquiry: new law", "0 percent to 90 percent with creativity", "fixed combination grammar"], ["structure-only isomorphism", "pair ranking 0.80 AUROC, 64 percent of patterns recovered with the language model", "much weaker alone than with the hunch"]])],
 [("What does artificial curiosity reward?", ["Compression progress", "Surprise alone", "Speed", "Length"], 0, "Learning something that shortens the description."), ("Why is noise never chosen?", ["Nothing predicts it, so no progress", "It is too long", "It is illegal", "It is sorted last"], 0, "Surprise without learnability earns nothing."), ("When did curiosity help the inquiry agent most?", ["When its model class was missing the true law", "When the law was known", "Never", "Only with noise off"], 0, "It kept searching and triggered invention."), ("What did the creative step do?", ["Combined known patterns into new hypotheses", "Deleted data", "Raised the cost", "Stopped the agent"], 0, "Sum or gating of library patterns."), ("What is the best use of structure matching here?", ["Checking a language model's hunch and writing the rule", "Replacing the reasoner", "Finding single edges", "Sorting notes by date"], 0, "It verified hunches with 99 percent precision.")],
 [("What is compression progress?", "How much shorter the data description became after learning."), ("Why can invention fail from embeddings alone?", "They carry only part of the shape signal."), ("What does the planner use to look ahead?", "Monte-Carlo tree search over simulated futures."), ("What did the language model find?", "Shared mechanisms across domains, with 0.99 precision on clear notes.")],
 [PL("Score a hypothesis", "Write progress(stated, derived, label_cost). stated is the list of claims a note already makes; derived is the list of claims the reasoner derives once the hypothesis is added. Return how many stated claims are also derived, minus label_cost.", "progress(stated, derived, label_cost)", '''
  def progress(stated, derived, label_cost):
      return len([c for c in stated if c in derived]) - label_cost
  ''', [[["causes runaway_growth"], ["causes runaway_growth", "needs noise"], 1], [["happens monday"], ["causes runaway_growth"], 1], [[], [], 1]], "Count the stated claims that also appear in derived."),
  PL("Information gain in bits", "Write info_gain(prior, likelihoods). Both are lists of the same length. Multiply each prior by its likelihood, divide by the total to get the posterior, and return the sum over hypotheses of posterior times log base 2 of posterior over prior, rounded to 3 decimals. Skip hypotheses whose posterior is 0.", "info_gain(prior, likelihoods)", '''
  import math
  def info_gain(prior, likelihoods):
      w = [p * l for p, l in zip(prior, likelihoods)]
      t = sum(w)
      post = [x / t for x in w]
      return round(sum(q * math.log2(q / p) for q, p in zip(post, prior) if q > 0), 3)
  ''', [[[0.5, 0.5], [1, 1]], [[0.5, 0.5], [1, 0]], [[0.25, 0.25, 0.5], [0.5, 0.5, 1.0]], [[0.5, 0.5], [0.9, 0.1]]], "Bayes update, then the Kullback-Leibler divergence in bits.", approx=0.001),
  PL("Same loop?", "Write same_loop(a, b). Each argument is a list of signs, one per edge, for a loop that goes around once (for example [\"+\", \"+\", \"+\"] is a growth loop). Two loops have the same shape if they have the same number of edges and the same number of minus signs. Return True or False.", "same_loop(a, b)", '''
  def same_loop(a, b):
      return len(a) == len(b) and a.count("-") == b.count("-")
  ''', [[["+", "+"], ["+", "+"]], [["+", "-"], ["-", "+"]], [["+", "+", "+"], ["+", "+"]], [["+", "-"], ["+", "+"]]], "Compare the length and the count of minus signs."),
  MATCH("Match idea and role", "Pair each part with its job.", [("curiosity", "rewards compression progress"), ("mixture", "weights hypotheses"), ("tree search", "plans experiments"), ("invention", "combines known patterns")]),
  FILL("Curiosity", "Be curious about what you can {{learn}}, not about {{noise}}.")]))
